// Rank damage dice (Table 37, p. 176): roll the die closest to your Rank
// without going over. Not part of base damage, so it is not doubled on a crit.
const DCC_RANK_DAMAGE = [
  { min: 1, max: 1, dice: '+1' },
  { min: 2, max: 3, dice: '+1d2' },
  { min: 4, max: 5, dice: '+1d4' },
  { min: 6, max: 7, dice: '+1d6' },
  { min: 8, max: 9, dice: '+1d8' },
  { min: 10, max: 11, dice: '+1d10' },
  { min: 12, max: 13, dice: '+1d12' },
  { min: 14, max: 15, dice: '+1d8 & +1d6' },
  { min: 16, max: 17, dice: '+2d8' },
  { min: 18, max: 19, dice: '+1d10 & +1d8' },
  { min: 20, max: 20, dice: '+2d10' },
];

function dccRankDamage(rank) {
  const r = Number(rank) || 0;
  const row = DCC_RANK_DAMAGE.find(x => r >= x.min && r <= x.max);
  return row ? row.dice : '';
}

function dccSkill(id) { return DCC_SKILLS.find(s => s.id === id) || null; }
function dccSkillByName(name) {
  const n = String(name || '').toLowerCase();
  return DCC_SKILLS.find(s => s.name.toLowerCase() === n) || null;
}
